def _parse_release_version(part):
    """
    Takes a string like "1.0.4.0" and turns it into (1, 0, 4).
    """
    return tuple(
        reversed(
            list(
                itertools.dropwhile(
                    lambda x: x == 0,
                    reversed(list(int(i) for i in part.split("."))),
                )
            )
        )
    )
